/* From Uiverse.io by JoseIsra - Tags: card, flip */
.__UIV_SCOPE__ .card {
  width: 12rem;
  cursor: pointer;
}

.__UIV_SCOPE__ .content {
  text-align: center;
  position: relative;
  transition: all 2.25s;
  background-color: rgb(127, 204, 240);
  padding: 5em;
  transform-style: preserve-3d;
}

.__UIV_SCOPE__ .card:hover .content {
  transform: rotateY(0.5turn);
}

.__UIV_SCOPE__ .front,
.__UIV_SCOPE__ .back {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  padding: 2em;
  transform-style: preserve-3d;
  backface-visibility: hidden;
}

.__UIV_SCOPE__ .title {
  transform: translateZ(5rem);
  font-size: 2rem;
}

.__UIV_SCOPE__ .subtitle {
  transform: translateZ(2rem);
}

.__UIV_SCOPE__ .back {
  transform: rotateY(0.5turn);
  background-color: #009bff;
}

.__UIV_SCOPE__ .description {
  transform: translateZ(3rem);
}
